  for (const e of u.eq){ const q=e.fx.find(a=>a[1]==='equip'); if (q && q[4] && q[4].split(' ').includes(k)) return true; }
  for (const e of u.auras){ const q=e.fx.find(a=>a[1]==='aura'); if (q && q[4] && q[4].split(' ').includes(k)) return true; }
