      const O=S.p[1-Q.i];
      for (const ab of u.c.fx) if (ab[0]==='death'){ if (ab[1]==='recur'){ if (!u.tok && Q.disc.includes(u.c)){ Q.disc.splice(Q.disc.lastIndexOf(u.c),1); Q.hand.push(u.c); } } else run(S,Q,O,ab,{card:u.c,self:u,dead:true}); }
