function applyTrade(s, items){ for (const e of items){ const o=objOf(e); if (!o || o.o!==0) continue; o.o=HSID(s.id); if (e.t!=='s') (o.h=o.h||[]).push([G.day,'Traded to '+whereName(s),0,'']); addEntry(s,{t:e.t,id:e.id}); } }
