    if (m===9 && dd===17) add('scon',{ann:t-60}); if (m===10 && dd===8) add('rcon',{ann:t-60}); if (m===7 && dd===23) add('bcon',{ann:t-75}); if (m===4 && dw===6 && dd<=7) add('ccon',{ann:t-60});
