  const pel=[125, 236+(P.py||0)]; const dir=pv(180+P.lean,1); const perp=[-dir[1], dir[0]];
  const sc=add2(pel, pv(180+P.lean, 84)); const head=add2(sc, pv(180+P.lean, 40));
