  out.push(`<path d="M${r2(sc[0])} ${r2(sc[1]+2)} L${r2(pel[0])} ${r2(pel[1]-6)}" stroke="${c1}" stroke-width="2" opacity=".6"/>`);
  out.push(`<path d="M${r2(tp[3][0])} ${r2(tp[3][1]-4)} L${r2(tp[2][0])} ${r2(tp[2][1]-4)}" stroke="${shade(c1,-0.2)}" stroke-width="6"/>`);
