  o += `<circle cx="${lh[0]}" cy="${lh[1]}" r="6" fill="${L.hero?c2:L.skin}" stroke="${K}" stroke-width="1.5"/><circle cx="${rh[0]}" cy="${rh[1]}" r="6" fill="${L.hero?c2:L.skin}" stroke="${K}" stroke-width="1.5"/>`;
