    const em=new T.MeshPhysicalMaterial({color:edgeCol, roughness:isSlab?0.12:0.5, metalness:(fin==='chrome'||fin==='refr'||fin==='foil'||fin==='super')&&!isSlab?0.5:0, clearcoat:isSlab?1:0.3, envMapIntensity:1.1}); em.envMap=env;
