  o+=`<rect x="17" y="276" width="216" height="52" rx="3" fill="url(#${u}p)" stroke="#000" stroke-opacity=".5"/>${orb(125,302,15,c.el)}<text x="24" y="290" ${TS} font-size="8.5" fill="#1b1612">Tap: add one ${tesc(c.el)} energy.</text>`;
