function discardChoice(x){ const a=mainAttack(x); let best=x.en.length-1; for (let i=0;i<x.en.length;i++){ const rest=x.en.filter((_,j)=>j!==i); if (payable(x,a.cost,rest)) { best=i; break; } } return best; }
