  const rounds=Math.ceil(Math.log2(N))+(kind==='champ'?1:0);
  for (let r=0;r<rounds;r++){ P.sort((x,y)=>y.w-x.w||y.tb-x.tb); for (let i=0;i+1<P.length;i+=2) game(P[i],P[i+1]).w++; if (P.length%2) P[P.length-1].w++; P.forEach(p=>p.tb=R()); }
