  const old=G.xtg.usage; for (const cid in U) old[cid]=0.6*(old[cid]||0)+0.4*Math.min(3,U[cid]); for (const cid in old){ if (U[cid]==null){ old[cid]*=0.7; if (old[cid]<0.02) delete old[cid]; } }
