  if (da && db && !G._xtCatch){ const r=TMR.play(da,db,hsh('final'+G.seed+':'+t)); if (r.w>=0){ champ=r.w===0? sf[0] : sf[1]; } fin={turns:r.turns, why:r.why, hb:r.harbor}; }
